212	    var ctx = canvas.getContext("2d");
213	    var dpr = Math.min(window.devicePixelRatio || 1, 2);
214	    var W = 0, H = 0;
215	    function resize() {
216	      W = window.innerWidth; H = window.innerHeight;
217	      canvas.width = W * dpr; canvas.height = H * dpr;
218	      canvas.style.width = W + "px"; canvas.style.height = H + "px";
