228	    function addParticles(x, y, speed) {
229	      var count = Math.min(3 + Math.floor(speed / 6), 8);
230	      for (var i = 0; i < count; i++) {
231	        particles.push({
232	          x: x, y: y,
233	          vx: (Math.random() - 0.5) * 1.4,
234	          vy: (Math.random() - 0.5) * 1.4,
235	          life: 1,
236	          decay: 0.012 + Math.random() * 0.02,
237	          size: 2 + Math.random() * 5,
238	          color: PALETTE[(Math.random() * PALETTE.length) | 0]
239	        });
240	      }
241	    }
