243	    window.addEventListener("mousemove", function (e) {
244	      mouse.px = mouse.x; mouse.py = mouse.y;
245	      mouse.x = e.clientX; mouse.y = e.clientY;
246	      mouse.active = true;
247	      var dx = mouse.x - mouse.px, dy = mouse.y - mouse.py;
248	      var speed = Math.sqrt(dx * dx + dy * dy);
249	      if (speed > 1.5) addParticles(mouse.x, mouse.y, speed);
250	    });
251	    window.addEventListener("mouseout", function () { mouse.active = false; });
252	
253	    function loop() {
254	      ctx.clearRect(0, 0, W, H);
255	      for (var i = particles.length - 1; i >= 0; i--) {
256	        var p = particles[i];
257	        p.x += p.vx; p.y += p.vy; p.vy += 0.02; p.life -= p.decay;
258	        if (p.life <= 0) { particles.splice(i, 1); continue; }
259	        ctx.globalAlpha = Math.max(0, p.life);
260	        ctx.beginPath();
261	        ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
262	        ctx.fillStyle = p.color;
263	        ctx.fill();
264	      }
265	      ctx.globalAlpha = 1;
