    var layout = [
      { l: "30%", t: "6%",  w: "12%", h: "42%", tag: "FOUNDER" },
      { l: "48%", t: "18%", w: "15%", h: "58%", tag: "" },
      { l: "0%",  t: "34%", w: "20%", h: "45%", tag: "" },
      { l: "88%", t: "22%", w: "13%", h: "48%", tag: "" },
