      tile.appendChild(im);
      if (o.tag) {
        var t = document.createElement("span"); t.className = "tag"; t.textContent = o.tag;
        tile.appendChild(t);
      }
      tile.setAttribute("data-depth", (0.1 + i * 0.08).toFixed(2));
      wrap.appendChild(tile);
    });
