  /* =================================================================
     3. CASE STUDY CARDS
     ================================================================= */
  (function buildCases() {
    var track = document.getElementById("casesTrack");
    if (!track) return;
    CASES.forEach(function (c) {
      var card = document.createElement("article");
      card.className = "case-card";
      var media = document.createElement("div");
      media.className = "case-media";
